import { Component, computed, inject, signal } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { NgTemplateOutlet } from '@angular/common';
import { FormsModule } from '@angular/forms';
import {
  CdkDropListGroup, CdkDropList, CdkDrag, CdkDragPlaceholder, CdkDragDrop, transferArrayItem,
} from '@angular/cdk/drag-drop';
import {
  TablerIconComponent, IconChevronRight, IconArrowsMaximize,
  IconFilter, IconUsers, IconCalendar, IconClipboardText, IconCopy, IconPlus, IconTrash,
  IconList, IconClock, IconUser, IconGripVertical, IconChevronLeft,
} from '@tabler/icons-angular';
import {
  HrmAppShell, HrmButton, HrmSelect, HrmOption, HrmAvatar,
  HrmShiftCell, HrmShiftVariant, HrmShiftTone,
} from 'hrm-ui';
import { SgTemplateSideNav } from './_template-side-nav';
import { SgDoc } from '../../../doc/sg-doc';
import { SgUse, SgDo, SgDont } from '../../../doc/sg-blocks';

/** 1 ô ca. k = loại (opening/afternoon/night = ca làm; rest/holiday/absence = ngày đặc biệt). */
interface Cell { k: 'opening' | 'afternoon' | 'night' | 'admin' | 'rest' | 'holiday' | 'absence'; t?: string; }
/** shifts = 7 ngày, MỖI ngày là mảng 0-hoặc-1 ô (mảng-mỗi-ô ⇒ CDK transferArrayItem chuẩn). */
interface Emp { id: number; name: string; role: string; av: string; ph: string; shifts: Cell[][]; }

/** Doc page · Xếp ca cửa hàng (Template) — lịch xếp ca dạng scheduler TƯƠNG TÁC ĐẦY ĐỦ:
 *  kéo-thả ô ca giữa các ngày/nhân viên (đổi chỗ/hoán đổi), bấm ô trống để thêm ca (chọn loại),
 *  bấm ô ca để đổi/xoá, thêm/xoá nhân viên. Dải ĐỊNH BIÊN (coverage) + lưới NHÂN VIÊN × 7 ngày.
 *  Ô ca = component DS hrm-shift-cell. State = signal, design token. */
@Component({
  selector: 'sg-template-shift-schedule',
  imports: [
    NgTemplateOutlet, FormsModule, TablerIconComponent,
    CdkDropListGroup, CdkDropList, CdkDrag, CdkDragPlaceholder,
    HrmAppShell, SgTemplateSideNav, HrmButton, HrmSelect, HrmAvatar, HrmShiftCell,
    SgDoc, SgUse, SgDo, SgDont,
  ],
  template: `
    @if (preview) {
      <div class="lp-desktop lp-desktop--full"><ng-container *ngTemplateOutlet="screen" /></div>
    } @else {
    <sg-doc category="Template" title="Xếp ca cửa hàng"
      desc="Lịch xếp ca dạng scheduler TƯƠNG TÁC: kéo-thả ô ca giữa ngày/nhân viên (đổi chỗ · hoán đổi), bấm ô trống để thêm ca, bấm ô ca để đổi/xoá, thêm/xoá nhân viên. Dải ĐỊNH BIÊN (coverage) trên lưới NHÂN VIÊN × 7 ngày. Ô ca = hrm-shift-cell.">
      <div sgOverview>
        <div class="lp-desktop"><ng-container *ngTemplateOutlet="screen" /></div>
        <div class="lp-full">
          <a class="lp-full-link" href="/preview/shift-schedule" target="_blank" rel="noopener">
            <hrm-button variant="default"><tabler-icon [icon]="maximize" [size]="16" /> Mở toàn màn hình</hrm-button>
          </a>
        </div>
      </div>
      <div sgUsage>
        <sg-use purpose="Phân & theo dõi ca theo tuần đối chiếu định biên (coverage). Người xếp lịch KÉO-THẢ ca giữa các ô, thêm/đổi/xoá ca, thêm/xoá nhân viên — cân người theo khung giờ."
          [when]="when"
          behavior="Kéo 1 ô ca sang ô khác → chuyển ca (ô đích trống) hoặc HOÁN ĐỔI (ô đích đã có ca). Bấm ô trống → menu chọn loại ca (Ca Sáng/Chiều/Đêm/Hành chính/Ngày nghỉ/Nghỉ lễ/Vắng mặt). Bấm ô ca → đổi loại hoặc Xoá ca. Nút Thêm nhân viên chèn dòng mới; di chuột vào dòng → nút xoá."
          avoid="Không cho 1 ô chứa >1 ca (mỗi ô = 1 ca/ngày). Không kéo-thả vào dải ĐỊNH BIÊN (chỉ là nhu cầu, không phải phân công)." />
      </div>
      <div sgBest>
        <sg-do>Kéo-thả bằng CDK DragDrop (chuẩn hoá cùng hrm-board): ô đích trống → chuyển, có ca → hoán đổi.</sg-do>
        <sg-do>Thêm/đổi ca qua 1 popover chọn loại (token màu theo <code>hrm-shift-cell</code>).</sg-do>
        <sg-do>State là <code>signal</code> → đầu người/định biên cập nhật realtime khi sửa lịch.</sg-do>
        <sg-dont>Đừng để thao tác ẩn — ô trống có "＋", ô ca kéo được (con trỏ grab), dòng NV có nút xoá khi hover.</sg-dont>
      </div>
    </sg-doc>
    }

    <ng-template #screen>
      <hrm-app-shell contentPad="none">
        <sg-template-side-nav appSideNav selectedKey="shift" />

        <div class="ssh-scroll">
          <div class="sch-page">
            <div class="sch-head">
              <p class="sch-eyebrow">Chấm công · Xếp ca</p>
              <h1 class="sch-h1">Lịch xếp ca</h1>
            </div>

            <!-- Toolbar + lưới trong 1 panel trắng (đồng bộ toolbar chế độ xem thẻ/kanban) -->
            <div class="sch-panel">
            <div class="sch-toolbar">
              <div class="tb-left">
                <div class="sch-nav">
                  <button class="dy-nav" type="button" (click)="prevPeriod()" aria-label="Tuần trước"><tabler-icon [icon]="chevLeft" [size]="18" /></button>
                  <span class="sch-period">{{ periodLabel() }}</span>
                  <button class="dy-nav" type="button" (click)="nextPeriod()" aria-label="Tuần sau"><tabler-icon [icon]="caret" [size]="18" /></button>
                  <button class="sch-today" type="button" (click)="today()">Tuần này</button>
                </div>
                <hrm-select [options]="filterOpts" [(ngModel)]="filter" style="width:120px" />
                <hrm-select [options]="empOpts" [(ngModel)]="empView" style="width:140px" />
                <button class="tb-ico" type="button" aria-label="Ghi chú"><tabler-icon [icon]="notes" [size]="18" /></button>
              </div>
              <div class="tb-right">
                <hrm-button variant="default"><tabler-icon [icon]="copy" [size]="16" /> Chép tuần trước</hrm-button>
                <hrm-button variant="primary" (click)="addEmp()"><tabler-icon [icon]="plus" [size]="16" /> Thêm nhân viên</hrm-button>
                <button class="tb-ico tb-ico--danger" type="button" aria-label="Xoá tuần" (click)="clearWeek()"><tabler-icon [icon]="trash" [size]="18" /></button>
              </div>
            </div>

            <!-- Lưới xếp ca theo tuần -->
            <div class="sch-wrap">
              <div class="sch-grid" cdkDropListGroup>
                <!-- Coverage header: eyebrow + stats -->
                <div class="band cov-head">
                  <div class="cov-eyebrow">Định biên</div>
                  <div class="cov-stats">
                    <span class="cov-stat"><i class="dot dot--early"></i> Ca sáng: {{ early() }}</span>
                    <span class="cov-stat"><i class="dot dot--late"></i> Ca chiều: {{ late() }}</span>
                    <span class="cov-stat"><tabler-icon [icon]="clock" [size]="14" /> {{ totalHours() }}H 00M</span>
                    <span class="cov-stat"><tabler-icon [icon]="user" [size]="14" /> {{ headcount() }}</span>
                  </div>
                </div>

                <!-- Coverage cells: 2 demand blocks per day -->
                <div class="band cov-cells">
                  <div class="cov-views">
                    <hrm-button variant="default" size="small"><tabler-icon [icon]="list" [size]="15" /> Xem định biên</hrm-button>
                  </div>
                  @for (cv of cov(); track $index) {
                    <div class="cov-day" cdkDropList [cdkDropListData]="covData" [cdkDropListEnterPredicate]="rejectDrop" cdkDropListSortingDisabled>
                      @if (cv.remOp > 0) {
                        <div class="cov-drag" cdkDrag [cdkDragData]="{ k: 'opening', copy: true }">
                          <hrm-shift-cell variant="coverage" tone="opening" title="Ca Sáng" [time]="opTime" [count]="cv.remOp" />
                          <div class="cov-ph" *cdkDragPlaceholder></div>
                        </div>
                      }
                      @if (cv.remAf > 0) {
                        <div class="cov-drag" cdkDrag [cdkDragData]="{ k: 'afternoon', copy: true }">
                          <hrm-shift-cell variant="coverage" tone="afternoon" title="Chiều" [time]="afTime" [count]="cv.remAf" />
                          <div class="cov-ph" *cdkDragPlaceholder></div>
                        </div>
                      }
                    </div>
                  }
                </div>

                <!-- Coverage totals per day -->
                <div class="band cov-foot">
                  <div class="cov-foot-lead"></div>
                  @for (cv of cov(); track $index) {
                    <div class="cov-fday">
                      <tabler-icon [icon]="clock" [size]="13" /> {{ cv.heads * 8 }}H 00M
                      <span class="heads"><tabler-icon [icon]="user" [size]="13" /> {{ cv.heads }}</span>
                    </div>
                  }
                </div>

                <!-- Day header -->
                <div class="band day-head">
                  <div class="day-lead">Lịch: Nhân viên</div>
                  @for (wd of weekDates(); track $index; let i = $index) {
                    <div class="sch-dh"><span class="sch-dow">{{ dows[i] }}</span><span class="sch-date">{{ wd.getDate() }}/{{ wd.getMonth() + 1 }}</span></div>
                  }
                </div>

                <!-- Employee rows -->
                @for (e of emps(); track e.id; let ei = $index) {
                  <div class="band emp-row">
                    <div class="emp-info">
                      <hrm-avatar [text]="e.av" [colorSeed]="e.name" [colorful]="true" [size]="34" />
                      <span class="emp-meta">
                        <span class="emp-name">{{ e.name }}</span>
                        <span class="emp-hrs">{{ e.ph }}h · HĐ 40h</span>
                      </span>
                      <button class="emp-x" type="button" (click)="removeEmp(ei)" aria-label="Xoá nhân viên"><tabler-icon [icon]="trash" [size]="14" /></button>
                    </div>
                    @for (day of e.shifts; track $index; let di = $index) {
                      <div class="sch-cell" cdkDropList [cdkDropListData]="day" (cdkDropListDropped)="onDrop($event)">
                        @for (c of day; track $index) {
                          <div class="sch-card" cdkDrag (click)="openEdit(ei, di, $event)">
                            <hrm-shift-cell [variant]="KIND[c.k].variant" [tone]="KIND[c.k].tone"
                              [title]="KIND[c.k].title" [time]="c.t || ''" />
                            <div class="sch-card-ph" *cdkDragPlaceholder></div>
                          </div>
                        }
                        @if (!day.length) {
                          <button class="sch-empty" type="button" (click)="openAdd(ei, di, $event)" aria-label="Thêm ca"><tabler-icon [icon]="plus" [size]="16" /></button>
                        }
                      </div>
                    }
                  </div>
                }
              </div>
            </div>
            </div>

            <button class="sch-add" type="button" (click)="addEmp()"><tabler-icon [icon]="plus" [size]="16" /> Thêm nhân viên</button>
          </div>
        </div>
      </hrm-app-shell>
    </ng-template>

    <!-- Shift-type picker (thêm / đổi ca) -->
    @if (picker(); as p) {
      <div class="pk-backdrop" (click)="picker.set(null)"></div>
      <div class="pk" [style.left.px]="p.x" [style.top.px]="p.y">
        <div class="pk-h">{{ p.mode === 'add' ? 'Thêm ca' : 'Đổi ca' }}</div>
        @for (pr of presets; track pr.k) {
          <button class="pk-item" type="button" (click)="pick(pr.k)">
            <i [class]="'pk-dot pkd-' + pr.k"></i>{{ pr.label }}
          </button>
        }
        @if (p.mode === 'edit') {
          <div class="pk-sep"></div>
          <button class="pk-item pk-del" type="button" (click)="clearCell()"><tabler-icon [icon]="trash" [size]="14" /> Xoá ca</button>
        }
      </div>
    }
  `,
  styles: [`
    .lp-desktop { position: relative; height: 760px; border: 1px solid var(--border-sub); border-radius: var(--radius-xl); overflow: hidden; box-shadow: var(--shadow-regular-sm); }
    .lp-desktop--full { position: relative; height: 100vh; border: 0; border-radius: 0; box-shadow: none; }
    .lp-full { margin-top: 14px; } .lp-full-link { text-decoration: none; }
    .lp-desktop ::ng-deep .shell-content { padding: 0; }

    .ssh-scroll { height: 100%; overflow-y: auto; background: var(--bg-canvas, var(--bg-surface-subtle)); }
    .sch-page { max-width: 1440px; margin: 0 auto; padding: var(--space-5, 20px) var(--space-6, 24px) var(--space-10, 40px); }

    .sch-head { margin-bottom: var(--space-3, 12px); }
    .sch-eyebrow { margin: 0 0 2px; font-size: var(--fs-12, 12px); font-weight: var(--font-medium, 500); color: var(--text-soft); }
    .sch-h1 { margin: 0; font-size: var(--fs-22, 22px); font-weight: var(--font-bold, 700); color: var(--text-strong); letter-spacing: -.01em; }

    /* Toolbar */
    .sch-panel { background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-xl); overflow: hidden; }
    .sch-toolbar { display: flex; align-items: center; justify-content: space-between; gap: var(--space-3, 12px); padding: var(--space-2-5, 10px) var(--space-3-5, 14px); border-bottom: 1px solid var(--border-sub); flex-wrap: wrap; }
    .tb-left, .tb-right { display: flex; align-items: center; gap: var(--space-2, 8px); flex-wrap: wrap; }
    .tb-ico { display: grid; place-items: center; width: 34px; height: 34px; border: 1px solid var(--border-sub); background: var(--bg-surface); border-radius: var(--radius-md); cursor: pointer; color: var(--text-sub); }
    .tb-ico:hover { color: var(--text-strong); background: var(--bg-surface-subtle); }
    .tb-ico--danger:hover { color: var(--error-base); border-color: var(--error-base); }
    .sch-nav { display: flex; align-items: center; gap: 6px; }
    .sch-today { padding: 6px 12px; border: 1px solid var(--border-sub); background: var(--bg-surface); border-radius: var(--radius-md); font-size: var(--fs-13, 13px); font-weight: var(--font-medium, 500); color: var(--text-strong); cursor: pointer; }
    .sch-today:hover { background: var(--bg-surface-subtle); border-color: var(--primary-base); color: var(--primary-base); }
    .sch-period { font-size: var(--fs-14, 14px); font-weight: var(--font-semibold, 600); color: var(--text-strong); margin-left: 4px; white-space: nowrap; }

    /* Scheduler grid */
    .sch-wrap { overflow-x: auto; }
    .sch-grid { width: max-content; min-width: 100%; --cols: 220px repeat(7, minmax(158px, 1fr)); }
    .band { display: grid; grid-template-columns: var(--cols); }
    .band > :first-child { position: sticky; left: 0; z-index: 2; border-right: 1px solid var(--border-sub); }
    .band > :nth-child(2) { border-left: 0; }

    /* Coverage header */
    .cov-head { background: var(--bg-surface-subtle); border-bottom: 1px solid var(--border-sub); align-items: center; }
    .cov-head > :first-child { background: var(--bg-surface-subtle); }
    .cov-eyebrow { padding: var(--space-2-5, 10px) var(--space-3, 12px); font-size: var(--fs-11, 11px); font-weight: var(--font-bold, 700); letter-spacing: .05em; color: var(--text-soft); text-transform: uppercase; }
    .cov-stats { grid-column: 2 / -1; justify-self: end; display: flex; align-items: center; gap: var(--space-4, 16px); padding: var(--space-2, 8px) var(--space-3-5, 14px); flex-wrap: wrap; }
    .cov-stat { display: inline-flex; align-items: center; gap: 6px; font-size: var(--fs-12, 12px); font-weight: var(--font-semibold, 600); color: var(--text-sub); }
    .dot { width: 9px; height: 9px; border-radius: 50%; flex: none; }
    .dot--early { background: var(--data-7); } .dot--late { background: var(--data-1); }

    /* Coverage cells */
    .cov-cells { border-bottom: 1px solid var(--border-sub); }
    .cov-views { padding: var(--space-3, 12px); background: var(--bg-surface); display: flex; align-items: flex-start; }
    .cov-day { padding: var(--space-2, 8px); display: flex; flex-direction: column; gap: var(--space-2, 8px); border-left: 1px solid var(--border-sub); }
    .cov-drag { cursor: grab; border-radius: var(--radius-md); }
    .cov-drag:active { cursor: grabbing; }
    .cov-drag.cdk-drag-preview { box-shadow: var(--shadow-regular-md); }
    .cov-drag.cdk-drag-placeholder { opacity: .4; }

    /* Coverage totals */
    .cov-foot { background: var(--bg-surface-subtle); border-bottom: 1px solid var(--border-sub); }
    .cov-foot > :first-child { background: var(--bg-surface-subtle); }
    .cov-fday { padding: var(--space-2, 7px) var(--space-2-5, 10px); display: flex; align-items: center; gap: 6px; border-left: 1px solid var(--border-sub); font-size: var(--fs-12, 12px); color: var(--text-sub); font-variant-numeric: tabular-nums; }
    .cov-fday .heads { margin-left: auto; display: inline-flex; align-items: center; gap: 4px; }

    /* Day header */
    .day-head { background: var(--bg-surface); border-bottom: 1px solid var(--border-sub); }
    .day-head > :first-child { background: var(--bg-surface); }
    .day-lead { padding: var(--space-2-5, 10px) var(--space-3, 12px); font-size: var(--fs-11, 11px); font-weight: var(--font-bold, 700); letter-spacing: .05em; color: var(--text-soft); text-transform: uppercase; display: flex; align-items: center; }
    .sch-dh { padding: var(--space-2, 8px) var(--space-2-5, 10px); border-left: 1px solid var(--border-sub); display: flex; align-items: baseline; gap: 6px; }
    .sch-dow { font-size: var(--fs-12, 12px); font-weight: var(--font-bold, 700); color: var(--text-strong); }
    .sch-date { font-size: var(--fs-12, 12px); color: var(--text-soft); }

    /* Employee rows */
    .emp-row { border-bottom: 1px solid var(--border-sub); }
    .emp-row:last-child { border-bottom: 0; }
    .emp-info { padding: var(--space-2-5, 10px) var(--space-3, 12px); display: flex; align-items: center; gap: 10px; background: var(--bg-surface); }
    .emp-row:hover .emp-info { background: var(--bg-surface-subtle); }
    .emp-meta { flex: 1; min-width: 0; display: flex; flex-direction: column; }
    .emp-name { font-size: var(--fs-13, 13px); font-weight: var(--font-semibold, 600); color: var(--text-strong); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .emp-hrs { font-size: var(--fs-12, 12px); color: var(--text-soft); }
    .emp-x { flex: none; display: grid; place-items: center; width: 26px; height: 26px; border: 0; background: transparent; border-radius: var(--radius-md); color: var(--text-soft); cursor: pointer; opacity: 0; transition: opacity .12s; }
    .emp-row:hover .emp-x { opacity: 1; }
    .emp-x:hover { color: var(--error-base); background: color-mix(in srgb, var(--error-base) 12%, transparent); }

    .sch-cell { padding: var(--space-2, 8px); border-left: 1px solid var(--border-sub); min-height: 66px; display: flex; }
    .sch-card { flex: 1; display: flex; cursor: grab; border-radius: var(--radius-md); }
    .sch-card:active { cursor: grabbing; }
    .sch-card hrm-shift-cell { flex: 1; }
    .sch-empty { flex: 1; border: 1px dashed transparent; border-radius: var(--radius-md); background: transparent; cursor: pointer; display: grid; place-items: center; color: var(--text-soft); opacity: 0; transition: opacity .12s; }
    .sch-cell:hover .sch-empty { opacity: 1; border-color: var(--border-sub); }
    .sch-empty:hover { color: var(--primary-base); border-color: var(--primary-base); background: var(--primary-bg-subtle); }

    /* CDK drag-drop */
    .sch-card.cdk-drag-preview { box-shadow: var(--shadow-regular-md); }
    .sch-card.cdk-drag-placeholder { opacity: 0; }
    .cdk-drop-list-dragging .sch-card:not(.cdk-drag-placeholder) { transition: transform var(--duration-normal, .18s) var(--ease-out, ease); }
    .sch-cell.cdk-drop-list-receiving, .sch-cell.cdk-drop-list-dragging { background: var(--primary-bg-subtle); }
    .cdk-drag-animating { transition: transform var(--duration-normal, .2s) var(--ease-out, ease); }

    .sch-add { margin-top: var(--space-3, 12px); display: inline-flex; align-items: center; gap: 6px; padding: 8px 14px; border: 1px dashed var(--border-sub); background: var(--bg-surface); border-radius: var(--radius-lg); color: var(--text-sub); font-size: var(--fs-13, 13px); font-weight: var(--font-medium, 500); cursor: pointer; }
    .sch-add:hover { color: var(--primary-base); border-color: var(--primary-base); }

    /* Nút điều hướng tuần ‹ › */
    .dy-nav { display: grid; place-items: center; width: 30px; height: 30px; border: 1px solid var(--border-sub); background: var(--bg-surface); border-radius: var(--radius-md); cursor: pointer; color: var(--text-sub); }
    .dy-nav:hover { color: var(--text-strong); background: var(--bg-surface-subtle); }

    /* Picker popover */
    .pk-backdrop { position: fixed; inset: 0; z-index: 40; }
    .pk { position: fixed; z-index: 41; min-width: 214px; background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-lg); box-shadow: var(--shadow-regular-lg); padding: 6px; }
    .pk-h { padding: 6px 8px 4px; font-size: var(--fs-11, 11px); font-weight: var(--font-bold, 700); letter-spacing: .04em; text-transform: uppercase; color: var(--text-soft); }
    .pk-item { display: flex; align-items: center; gap: 9px; width: 100%; padding: 7px 8px; border: 0; background: transparent; border-radius: var(--radius-md); cursor: pointer; font-size: var(--fs-13, 13px); color: var(--text-strong); text-align: left; }
    .pk-item:hover { background: var(--bg-surface-subtle); }
    .pk-dot { width: 10px; height: 10px; border-radius: 50%; flex: none; }
    .pk-sep { height: 1px; background: var(--border-sub); margin: 4px 6px; }
    .pk-del { color: var(--error-base); gap: 7px; }
    .pk-del:hover { background: color-mix(in srgb, var(--error-base) 10%, transparent); }
    .pkd-opening { background: var(--data-7); } .pkd-afternoon { background: var(--data-1); }
    .pkd-night { background: var(--data-3); } .pkd-admin { background: var(--data-4); }
    .pkd-rest { background: var(--data-5); } .pkd-holiday { background: var(--data-8); }
    .pkd-absence { background: var(--warning-base); }
  `],
})
export class SgTemplateShiftSchedule {
  protected readonly preview = inject(ActivatedRoute).snapshot.data['preview'] === true;

  protected readonly caret = IconChevronRight;
  protected readonly chevLeft = IconChevronLeft;
  protected readonly maximize = IconArrowsMaximize;
  protected readonly notes = IconClipboardText;
  protected readonly copy = IconCopy;
  protected readonly plus = IconPlus;
  protected readonly trash = IconTrash;
  protected readonly list = IconList;
  protected readonly clock = IconClock;
  protected readonly user = IconUser;
  protected readonly grip = IconGripVertical;
  protected readonly when = ['Kéo-thả xếp ca theo tuần đối chiếu định biên', 'Thêm/đổi/xoá ca nhanh trong lưới', 'Thêm/xoá nhân viên khi cân người'];

  // ── toolbar selects (trang trí) ──
  private _filter = signal('all'); protected get filter() { return this._filter(); } protected set filter(v: string) { this._filter.set(v); }
  private _empView = signal('emp'); protected get empView() { return this._empView(); } protected set empView(v: string) { this._empView.set(v); }
  /** Mốc tuần đang xem — thanh ‹ Tuần này › đổi ±1 tuần. "Tuần này" = tuần chứa 17/08/2026. */
  readonly ref = signal<Date>(new Date(2026, 7, 17));
  protected readonly filterOpts: HrmOption[] = [{ value: 'all', label: 'Bộ lọc' }, { value: 'open', label: 'Còn trống' }, { value: 'conflict', label: 'Trùng ca' }];
  protected readonly empOpts: HrmOption[] = [{ value: 'emp', label: 'Nhân viên' }, { value: 'dept', label: 'Bộ phận' }, { value: 'role', label: 'Vị trí' }];
  protected readonly dows = ['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'];

  // ── Điều hướng tuần (‹ › + Tuần này + nhãn khoảng) ──
  private addDays(d: Date, n: number): Date { const r = new Date(d); r.setDate(r.getDate() + n); return r; }
  private dowIndex(d: Date): number { return (d.getDay() + 6) % 7; }        // Mon=0..Sun=6
  private mondayOf(d: Date): Date { return this.addDays(d, -this.dowIndex(d)); }
  /** 7 Date của tuần chứa `ref` (Mon→Sun) — cột lịch map 1-1 với mảng này. */
  protected readonly weekDates = computed(() => { const m = this.mondayOf(this.ref()); return Array.from({ length: 7 }, (_, i) => this.addDays(m, i)); });
  /** Nhãn khoảng tuần "dd/mm – dd/mm/yyyy". */
  protected readonly periodLabel = computed(() => {
    const w = this.weekDates(); const p = (n: number) => String(n).padStart(2, '0');
    return `${p(w[0].getDate())}/${p(w[0].getMonth() + 1)} – ${p(w[6].getDate())}/${p(w[6].getMonth() + 1)}/${w[6].getFullYear()}`;
  });
  protected prevPeriod(): void { this.ref.set(this.addDays(this.ref(), -7)); }
  protected nextPeriod(): void { this.ref.set(this.addDays(this.ref(), 7)); }
  protected today(): void { this.ref.set(new Date(2026, 7, 17)); }

  // ── loại ca → props hrm-shift-cell + preset chọn ca ──
  protected readonly KIND: Record<Cell['k'], { variant: HrmShiftVariant; tone: HrmShiftTone; title: string }> = {
    opening: { variant: 'shift', tone: 'opening', title: 'Ca Sáng' },
    afternoon: { variant: 'shift', tone: 'afternoon', title: 'Chiều' },
    night: { variant: 'shift', tone: 'night', title: 'Đêm' },
    admin: { variant: 'shift', tone: 'admin', title: 'Hành chính' },
    rest: { variant: 'rest', tone: 'rest', title: 'Ngày nghỉ' },
    holiday: { variant: 'block', tone: 'holiday', title: 'Nghỉ lễ' },
    absence: { variant: 'block', tone: 'absence', title: 'Vắng mặt' },
  };
  private readonly DTIME: Record<Cell['k'], string> = {
    opening: '08:00–13:00', afternoon: '15:00–20:00', night: '22:00–06:00', admin: '08:00–17:00',
    rest: '', holiday: '', absence: '',
  };
  protected readonly presets: { k: Cell['k']; label: string }[] = [
    { k: 'opening', label: 'Ca Sáng · 08:00–13:00' },
    { k: 'afternoon', label: 'Chiều · 15:00–20:00' },
    { k: 'night', label: 'Đêm · 22:00–06:00' },
    { k: 'admin', label: 'Hành chính · 08:00–17:00' },
    { k: 'rest', label: 'Ngày nghỉ' },
    { k: 'holiday', label: 'Nghỉ lễ' },
    { k: 'absence', label: 'Vắng mặt' },
  ];

  protected readonly opTime = '08:00–13:00';
  protected readonly afTime = '15:00–20:00';

  /** Nhu cầu ĐỊNH BIÊN mỗi ngày (CỐ ĐỊNH) = số ca đã xếp lúc đầu + badge còn thiếu ban đầu.
   *  ⇒ remaining ban đầu = [1,1,1,1,2,3,0] / [2,2,2,2,3,4,0] (giữ nguyên hình cũ), nhưng nay LIVE. */
  private readonly reqOp = [2, 3, 3, 3, 4, 3, 0];
  private readonly reqAf = [3, 4, 2, 3, 4, 5, 0];
  /** Coverage CÒN LẠI (reactive) = nhu cầu − số ca đã phân trong lịch. Kéo xuống gán ca → giảm;
   *  hết (0) → thẻ ẩn (@if); xoá/clear ca trong lịch → tăng lại → thẻ hiện lại. */
  protected readonly cov = computed(() => {
    const list = this.emps();
    return this.dows.map((_, di) => {
      const asgOp = list.filter((e) => e.shifts[di].some((s) => s.k === 'opening')).length;
      const asgAf = list.filter((e) => e.shifts[di].some((s) => s.k === 'afternoon')).length;
      const remOp = Math.max(0, this.reqOp[di] - asgOp);
      const remAf = Math.max(0, this.reqAf[di] - asgAf);
      return { remOp, remAf, heads: remOp + remAf };
    });
  });
  protected readonly early = computed(() => this.cov().reduce((a, c) => a + c.remOp, 0));
  protected readonly late = computed(() => this.cov().reduce((a, c) => a + c.remAf, 0));
  protected readonly totalHours = computed(() => this.cov().reduce((a, c) => a + c.heads * 8, 0));

  // ── STATE: lịch nhân viên (signal, mutable) ──
  protected readonly emps = signal<Emp[]>([
    { id: 1, name: 'Nguyễn Thị Mai Anh', role: 'Lễ tân', av: 'NA', ph: '0,0', shifts: [[], [], [{ k: 'holiday' }], [{ k: 'absence' }], [{ k: 'absence' }], [], []] },
    { id: 2, name: 'Trần Văn Hùng', role: 'Thu ngân', av: 'TH', ph: '15,0', shifts: [[{ k: 'rest' }], [{ k: 'opening', t: '08:00–13:00' }], [], [{ k: 'opening', t: '08:00–13:00' }], [{ k: 'opening', t: '08:00–13:00' }], [], []] },
    { id: 3, name: 'Lê Quốc Bảo', role: 'Bán hàng', av: 'LB', ph: '20,0', shifts: [[{ k: 'rest' }], [{ k: 'afternoon', t: '15:00–20:00' }], [], [{ k: 'afternoon', t: '15:00–20:00' }], [{ k: 'afternoon', t: '15:00–20:00' }], [{ k: 'afternoon', t: '15:00–20:00' }], []] },
    { id: 4, name: 'Phạm Hồng Nhung', role: 'CSKH', av: 'PN', ph: '20,0', shifts: [[{ k: 'opening', t: '08:00–13:00' }], [{ k: 'opening', t: '08:00–13:00' }], [{ k: 'opening', t: '08:00–13:00' }], [], [{ k: 'opening', t: '08:00–13:00' }], [], []] },
    { id: 5, name: 'Đỗ Minh Khoa', role: 'Kho vận', av: 'MK', ph: '5,0', shifts: [[{ k: 'afternoon', t: '15:00–20:00' }], [], [], [], [{ k: 'absence' }], [{ k: 'holiday' }], [{ k: 'absence' }]] },
    { id: 6, name: 'Vũ Thanh Tâm', role: 'Lễ tân', av: 'TT', ph: '10,0', shifts: [[], [{ k: 'afternoon', t: '15:00–20:00' }], [{ k: 'opening', t: '08:00–13:00' }], [{ k: 'opening', t: '08:00–13:00' }], [], [], []] },
  ]);
  private empSeq = 7;

  /** Đầu người có phân công ca (cập nhật realtime theo lịch). */
  protected readonly headcount = computed(() =>
    this.emps().filter((e) => e.shifts.some((day) => day.some((s) => s.k === 'opening' || s.k === 'afternoon' || s.k === 'night' || s.k === 'admin'))).length,
  );

  // ── picker (thêm / đổi ca) ──
  protected readonly picker = signal<{ ei: number; di: number; mode: 'add' | 'edit'; x: number; y: number } | null>(null);

  protected openAdd(ei: number, di: number, ev: MouseEvent): void { this.openPicker(ei, di, 'add', ev); }
  protected openEdit(ei: number, di: number, ev: MouseEvent): void { this.openPicker(ei, di, 'edit', ev); }
  private openPicker(ei: number, di: number, mode: 'add' | 'edit', ev: MouseEvent): void {
    ev.stopPropagation();
    const r = (ev.currentTarget as HTMLElement).getBoundingClientRect();
    const x = Math.min(r.left, window.innerWidth - 230);
    const y = Math.min(r.bottom + 4, window.innerHeight - 320);
    this.picker.set({ ei, di, mode, x, y });
  }
  protected pick(k: Cell['k']): void {
    const p = this.picker(); if (!p) return;
    const t = this.DTIME[k];
    this.setCell(p.ei, p.di, t ? { k, t } : { k });
    this.picker.set(null);
  }
  protected clearCell(): void {
    const p = this.picker(); if (!p) return;
    this.setCell(p.ei, p.di, null);
    this.picker.set(null);
  }
  private setCell(ei: number, di: number, cell: Cell | null): void {
    const day = this.emps()[ei].shifts[di];
    day.length = 0;
    if (cell) day.push(cell);
    this.bump();
  }

  // ── drag-drop (gán từ định biên · chuyển ca · hoán đổi) ──
  /** Ô coverage KHÔNG nhận thả (chỉ là nguồn kéo — nhu cầu, không phải phân công). */
  protected readonly rejectDrop = (): boolean => false;
  /** Data giả cho cdkDropList của coverage (không bao giờ bị mutate). */
  protected readonly covData: unknown[] = [];

  protected onDrop(e: CdkDragDrop<Cell[]>): void {
    const data = e.item.data as { k: Cell['k']; copy?: boolean } | undefined;
    // Kéo từ dải ĐỊNH BIÊN → GÁN ca cho nhân viên (COPY: nhu cầu vẫn giữ nguyên).
    if (data?.copy) {
      const t = this.DTIME[data.k];
      const to = e.container.data;
      to.length = 0;
      to.push(t ? { k: data.k, t } : { k: data.k });
      this.bump();
      return;
    }
    // Kéo ô ca giữa nhân viên: đích trống → chuyển; đích có ca → hoán đổi.
    if (e.previousContainer === e.container) return;
    const from = e.previousContainer.data;
    const to = e.container.data;
    if (to.length === 0) {
      transferArrayItem(from, to, e.previousIndex, 0);
    } else {
      const moved = from[e.previousIndex];
      from[e.previousIndex] = to[0];
      to[0] = moved;
    }
    this.bump();
  }

  // ── thêm / xoá nhân viên · xoá tuần ──
  protected addEmp(): void {
    const id = this.empSeq++;
    this.emps.update((list) => [...list, {
      id, name: 'Nhân viên mới', role: 'Chưa xếp ca', av: 'NV', ph: '0,0',
      shifts: Array.from({ length: 7 }, () => [] as Cell[]),
    }]);
  }
  protected removeEmp(ei: number): void { this.emps.update((list) => list.filter((_, i) => i !== ei)); }
  protected clearWeek(): void {
    this.emps.update((list) => list.map((e) => ({ ...e, shifts: e.shifts.map(() => [] as Cell[]) })));
  }

  /** Ép re-render sau khi mutate mảng lồng (signal shallow). */
  private bump(): void { this.emps.set([...this.emps()]); }
}
